mapper.select:
SELECT id, tree_id, tree_name, template_type, tree_status, creator, modifier, create_time, update_time, tenant_id, industry_code, app_ver_code FROM vm_device_diy_tree_t WHERE delete_flag = '0' AND tenant_id = #{tenantId} AND industry_code = #{industryCode}
AND tree_status = #{treeStatus}
ORDER BY create_time desc

SELECT DISTINCT t.id, t.node_type, t.node_code as code, t.node_value as name, t.node_level as level, t.parent_node_code as parentCode, m.device_code, m.device_name, ch.channel_code, ch.channel_name, ch.channel_status AS STATUS, m.longitude, m.latitude, ch.facade, m.category_code, m.site_code, m.device_status, ( CASE WHEN IFNULL( dc.user_device_coll_id, 0 ) = 0 THEN '0' ELSE '1' END ) isMonitor, m.image_url FROM vm_device_diy_tree_node_t t LEFT JOIN vm_channel_info_t ch ON ch.channel_code = t.channel_code and t.device_code = ch.device_code LEFT JOIN vm_device_info_t m ON t.device_code = m.device_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '5' AND dct.user_id = #{userId} LEFT JOIN vm_user_device_collection_t dc ON dc.coll_obj_code = ch.channel_code AND dc.coll_obj_type = '6' AND dc.user_id = #{userId} LEFT JOIN vm_order_devices ord ON t.device_code = ord.device_code AND t.tenant_id = ord.tenant_id AND t.industry_code = ord.industry_code WHERE t.delete_flag = '0' AND ord.ord_status IN ( 0, 1, 2 ) AND ord.delete_flag = '0' AND t.tree_id = #{treeId} ${dataScope}
AND m.category_code in
#{item}
AND ch.channel_status in
#{item}
AND dc.user_device_coll_id IS NOT NULL

mapper.update:
update vm_device_diy_tree_t
tree_name = #{treeName}, template_type = #{templateType}, tree_status = #{treeStatus}, modifier = #{modifier}, update_time = now()
where tree_id = #{treeId}

